-- Declared foreign keys for performance module, added where the database lacks them
-- Generated by metaphor-schema

DO $$
BEGIN
    IF to_regclass('performance.appraisals') IS NOT NULL AND to_regclass('performance.appraisal_cycles') IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM pg_constraint c
        JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY (c.conkey)
        WHERE c.conrelid = to_regclass('performance.appraisals') AND c.contype = 'f' AND a.attname = 'cycle_id'
    ) THEN
        ALTER TABLE performance.appraisals ADD CONSTRAINT fk_appraisals_cycle_id FOREIGN KEY (cycle_id) REFERENCES performance.appraisal_cycles (id) NOT VALID;
        BEGIN
            ALTER TABLE performance.appraisals VALIDATE CONSTRAINT fk_appraisals_cycle_id;
        EXCEPTION WHEN foreign_key_violation THEN
            RAISE NOTICE 'fk_appraisals_cycle_id left NOT VALID: stored rows of performance.appraisals reference missing rows';
        END;
    END IF;
END $$;

